package com.ruoyi.medical.persistence;
import com.fasterxml.jackson.databind.JsonNode;
import com.ruoyi.medical.contracts.*;
import com.ruoyi.medical.persistence.mapper.*;
import java.io.*;import java.time.*;import java.util.*;
/** Fixed runtime-only approval. SOURCE policy rows cannot satisfy this authority. */
public final class RuntimeRetentionAuthority {
 private final RuntimeRetentionMapper mapper;private final PermissionMapper permissions;private final ResourceReadAuthority resources;private final PermissionAuthority grants;private final RuntimeRetentionSchema schema;private final com.ruoyi.medical.identity.PlatformMemberIdentityStatus identities;private final int maximumCandidates;
 public RuntimeRetentionAuthority(RuntimeRetentionMapper mapper,PermissionMapper permissions,ResourceReadAuthority resources,PermissionAuthority grants,RuntimeRetentionSchema schema,com.ruoyi.medical.identity.PlatformMemberIdentityStatus identities,int maximumCandidates){this.mapper=mapper;this.permissions=permissions;this.resources=resources;this.grants=grants;this.schema=schema;this.identities=identities;if(maximumCandidates<1||maximumCandidates>100)throw new IllegalArgumentException("Retention candidate capacity 1..100 required");this.maximumCandidates=maximumCandidates;}
 public final class Verified {
  private final EnterpriseAccess.Admission admission;private final String id,project,classification,purpose,digest;private final JsonNode fixed;private final List<PermissionProtocol.GrantRow> witnesses;
  private Verified(EnterpriseAccess.Admission a,String id,String project,String classification,String purpose,JsonNode fixed,RuntimeRetentionMapper.State lifecycle,List<PermissionProtocol.GrantRow> witnesses)throws IOException{this.admission=a;this.id=id;this.project=project;this.classification=classification;this.purpose=purpose;this.fixed=fixed.deepCopy();this.witnesses=List.copyOf(witnesses);digest=schema.hash(Map.of("fixed",fixed,"lifecycle",lifecycle,"grants",witnesses));}
  public PermissionProtocol.Scope ownerScope(){return scope(fixed.required("tenant_id").textValue(),nullable(fixed.required("request").required("project_id")));}
  public String policyRevision(){return id;} public String contentSha256()throws IOException{return schema.hash(fixed);} public JsonNode terms(){return fixed.required("request").required("terms").deepCopy();} public List<PermissionProtocol.GrantRow> authorizations(){return witnesses;}
  public void requireUnchanged()throws IOException{Verified now=requireForRun(admission,project,classification,purpose);if(!id.equals(now.id)||!digest.equals(now.digest))reject(ErrorCode.SCOPE_STALE);}
 }
 public Verified requireFixedForRun(EnterpriseAccess.Admission a,String id,String expectedHash,String project,String classification,String purpose)throws IOException{WireValues.uuid(id);WireValues.hash(expectedHash);var proof=requireForRun(a,project,classification,purpose);if(!id.equals(proof.policyRevision())||!expectedHash.equals(proof.contentSha256()))reject(ErrorCode.SCOPE_STALE);return proof;}
 public Verified requireForRun(EnterpriseAccess.Admission a,String project,String classification,String purpose)throws IOException{
  stage(purpose);WireValues.uuid(project);var v=new HashMap<String,Object>();v.put("userId",a.actorId());v.put("projectId",project);v.put("classification",classification);v.put("now",permissions.databaseTime());
  v.put("limit",maximumCandidates+1);var ids=mapper.candidates(v);if(ids.size()>maximumCandidates)reject(ErrorCode.CONTEXT_LIMIT);var active=new ArrayList<String>();for(String id:ids){var candidate=one(mapper.fixed(RuntimeRetentionAuthority.parameters("policyRevision",id)));if(!id.equals(candidate.policyRevision()))reject(ErrorCode.CONTENT_MISMATCH);verify(candidate);var life=lifecycle(candidate);if(life.retiredAt()==null||((LocalDateTime)v.get("now")).toInstant(ZoneOffset.UTC).isBefore(Instant.parse(life.retiredAt())))active.add(id);}if(active.isEmpty())reject(ErrorCode.DEPENDENCY_UNAVAILABLE);if(active.size()!=1)reject(ErrorCode.REVISION_CONFLICT);return require(a,active.get(0),project,classification,purpose);
 }
 public Verified require(EnterpriseAccess.Admission a,String id,String project,String classification,String purpose)throws IOException{
  stage(purpose);WireValues.uuid(id);WireValues.uuid(project);var row=one(mapper.fixed(RuntimeRetentionAuthority.parameters("policyRevision",id)));
  if(!id.equals(row.policyRevision()))reject(ErrorCode.CONTENT_MISMATCH);JsonNode fixed=verify(row);var lifecycle=lifecycle(row);var request=fixed.required("request");String ownerProject=nullable(request.required("project_id"));
  if(ownerProject!=null&&!ownerProject.equals(project)||!classification.equals(request.required("classification").textValue()))reject(ErrorCode.ACCESS_DENIED);
  LocalDateTime now=permissions.databaseTime();Instant instant=now.toInstant(ZoneOffset.UTC);if(lifecycle.retiredAt()!=null&&!instant.isBefore(Instant.parse(lifecycle.retiredAt())))reject(ErrorCode.DEPENDENCY_UNAVAILABLE);
  if(instant.isBefore(Instant.parse(request.required("effective_from").textValue()))||!instant.isBefore(Instant.parse(request.required("effective_until").textValue())))reject(ErrorCode.DEPENDENCY_UNAVAILABLE);
  var scope=scope(a.context().tenant_id(),ownerProject);var read=resources.require(a,scope,"retention.read",purpose);
  String approver=fixed.required("approved_by").textValue();var member=one(permissions.targetMember(approver));var binding=one(permissions.targetBinding(approver));
  if(!"ACTIVE".equals(member.status())||!approver.equals(member.userId())||!a.context().tenant_id().equals(member.tenantId())||member.validFrom().isAfter(now)||member.validTo()!=null&&!member.validTo().isAfter(now)||!"ACTIVE".equals(binding.status())||!approver.equals(binding.userId()))reject(ErrorCode.ACCESS_DENIED);
  if(!Set.of("local","oidc").contains(binding.mode())||"local".equals(binding.mode())&&!approver.equals(binding.localUserId())||"oidc".equals(binding.mode())&&binding.localUserId()!=null||!identities.active(new com.ruoyi.medical.identity.AuthenticatedIdentityBinding.View(binding.mode(),binding.userId(),binding.issuer(),binding.subject())))reject(ErrorCode.ACCESS_DENIED);
  var grant=one(permissions.currentGrant(fixed.required("approval_grant").required("grant_id").textValue()));
  grants.requireResource(scope,approver,binding.mode(),"retention.approve","RUNTIME_RETENTION_APPROVAL",List.of(grant),now);
  if(!grant.revision().toString().equals(fixed.required("approval_grant").required("revision").textValue()))reject(ErrorCode.SCOPE_STALE);
  return new Verified(a,id,project,classification,purpose,fixed,lifecycle,List.of(read,grant));
 }
 JsonNode verify(RuntimeRetentionMapper.Row row)throws IOException{
  var fixed=schema.validate("RetentionFixed",schema.read(row.fixedJson()));var request=fixed.required("request");var receipt=schema.validate("RetentionReceipt",schema.read(row.receiptJson()));
  if(!TenantScope.requireCurrent().tenantId().equals(row.tenantId())||!row.tenantId().equals(fixed.required("tenant_id").textValue())||!row.policyRevision().equals(fixed.required("policy_revision").textValue())||!row.creator().equals(fixed.required("approved_by").textValue())||!Instant.parse(row.createdAt()).equals(Instant.parse(fixed.required("approved_at").textValue()))||!Objects.equals(row.projectId(),nullable(request.required("project_id")))||!row.classification().equals(request.required("classification").textValue())||!"1.0.0".equals(row.schemaVersion())||!schema.manifest().equals(row.manifest())||!schema.hash(fixed).equals(row.contentHash())||!schema.hash(request).equals(row.requestHash())||!schema.read(row.requestJson()).equals(request))reject(ErrorCode.CONTENT_MISMATCH);
  if(!row.policyRevision().equals(receipt.required("policy_revision").textValue())||!row.operationId().equals(receipt.required("operation_id").textValue())||!row.requestHash().equals(receipt.required("request_body_sha256").textValue())||!row.contentHash().equals(receipt.required("content_sha256").textValue()))reject(ErrorCode.CONTENT_MISMATCH);
  var witness=approvalWitness(receipt,row.sessionId(),row.contextJson(),row.key(),row.createdAt());var v=values(row);if(!row.contentHash().equals(one(mapper.registry(v)))||!schema.read(one(mapper.operation(v))).equals(receipt)||!schema.read(one(mapper.audit(v))).equals(witness)||!schema.read(one(mapper.event(v))).equals(witness))reject(ErrorCode.CONTENT_MISMATCH);
  return fixed;
 }
 RuntimeRetentionMapper.State lifecycle(RuntimeRetentionMapper.Row policy)throws IOException{
  var state=one(mapper.state(RuntimeRetentionAuthority.parameters("policyRevision",policy.policyRevision())));
  if(!state.tenantId().equals(policy.tenantId())||!Objects.equals(state.projectId(),policy.projectId())||!state.policyRevision().equals(policy.policyRevision())||!state.schemaVersion().equals(policy.schemaVersion())||!state.manifest().equals(policy.manifest())||!state.classification().equals(policy.classification())||!state.createdBy().equals(policy.creator())||!Instant.parse(state.createdAt()).equals(Instant.parse(policy.createdAt())))reject(ErrorCode.CONTENT_MISMATCH);
  if(state.retiredAt()==null){if(state.decisionId()!=null||!"1".equals(state.revision())||!Instant.parse(state.updatedAt()).equals(Instant.parse(state.createdAt())))reject(ErrorCode.CONTENT_MISMATCH);}
  else{if(state.decisionId()==null||!"2".equals(state.revision()))reject(ErrorCode.CONTENT_MISMATCH);var row=one(mapper.retirement(RuntimeRetentionAuthority.parameters("decisionId",state.decisionId())));var decision=verifyRetirement(row);if(!Instant.parse(state.updatedAt()).equals(Instant.parse(row.createdAt()))||!row.classification().equals(policy.classification())||!policy.policyRevision().equals(decision.required("policy_revision").textValue())||!Objects.equals(policy.projectId(),nullable(decision.required("project_id")))||!Instant.parse(state.retiredAt()).equals(Instant.parse(decision.required("effective_at").textValue())))reject(ErrorCode.CONTENT_MISMATCH);}
  return state;
 }
 JsonNode verifyRetirement(RuntimeRetentionMapper.Retirement row)throws IOException{
  var d=schema.validate("Retirement",schema.read(row.fixedJson()));if(!TenantScope.requireCurrent().tenantId().equals(row.tenantId())||!row.tenantId().equals(d.required("tenant_id").textValue())||!Objects.equals(row.projectId(),nullable(d.required("project_id")))||!row.decisionId().equals(d.required("decision_id").textValue())||!row.policyRevision().equals(d.required("policy_revision").textValue())||!row.operationId().equals(d.required("operation_id").textValue())||!row.createdBy().equals(d.required("decided_by").textValue())||!Instant.parse(row.createdAt()).equals(Instant.parse(d.required("decided_at").textValue()))||Instant.parse(d.required("effective_at").textValue()).isBefore(Instant.parse(row.createdAt()))||!schema.hash(d).equals(row.contentHash())||!"1.0.0".equals(row.schemaVersion())||!schema.manifest().equals(row.manifest()))reject(ErrorCode.CONTENT_MISMATCH);
  var originalPolicy=one(mapper.fixed(RuntimeRetentionAuthority.parameters("policyRevision",row.policyRevision())));verify(originalPolicy);if(!originalPolicy.tenantId().equals(row.tenantId())||!Objects.equals(originalPolicy.projectId(),row.projectId())||!originalPolicy.classification().equals(row.classification()))reject(ErrorCode.CONTENT_MISMATCH);
  var request=d.required("original_request");boolean replacement=d.required("kind").asText().equals("REPLACE");
  if(replacement){if(d.required("replacement_policy_revision").isNull()||!d.required("replacement_policy_revision").equals(d.required("operation_target_id"))||!request.required("replaces").required("policy_revision").equals(d.required("policy_revision"))||!request.required("replaces").required("expected_revision").equals(d.required("expected_revision"))||!request.required("effective_from").equals(d.required("effective_at")))reject(ErrorCode.CONTENT_MISMATCH);
   var next=one(mapper.fixed(RuntimeRetentionAuthority.parameters("policyRevision",d.required("replacement_policy_revision").textValue())));var fixed=verify(next);if(!row.operationId().equals(next.operationId())||!row.key().equals(next.key())||!request.equals(fixed.required("request"))||!schema.read(next.receiptJson()).equals(d.required("operation_receipt")))reject(ErrorCode.CONTENT_MISMATCH);
  }else if(!d.required("replacement_policy_revision").isNull()||!d.required("policy_revision").equals(d.required("operation_target_id"))||!request.required("policy_revision").equals(d.required("policy_revision"))||!request.required("expected_revision").equals(d.required("expected_revision"))||!request.required("effective_at").equals(d.required("effective_at")))reject(ErrorCode.CONTENT_MISMATCH);
  RuntimeRetentionSchema.key(row.key());if(!schema.hash(request).equals(d.required("original_request_sha256").textValue())||!replacement&&!d.required("operation_receipt").equals(jsonSafeRetirement(d)))reject(ErrorCode.CONTENT_MISMATCH);
  var v=new HashMap<String,Object>();v.put("userId",TenantScope.requireCurrent().subjectId());v.put("decisionId",row.decisionId());v.put("projectId",row.projectId());v.put("creator",row.createdBy());v.put("operationId",row.operationId());v.put("key",row.key());v.put("requestHash",d.required("original_request_sha256").textValue());v.put("operationTarget",d.required("operation_target_id").textValue());v.put("operationName",replacement?"RUNTIME-RETENTION-APPROVE":"RUNTIME-RETENTION-RETIRE");v.put("httpStatus",replacement?201:200);v.put("manifest",row.manifest());v.put("classification",row.classification());v.put("auditId",d.required("audit_id").textValue());v.put("eventId",d.required("event_id").textValue());
  var witness=retirementWitness(d);if(!schema.read(one(mapper.retirementOperation(v))).equals(d.required("operation_receipt"))||!schema.read(one(mapper.retirementAudit(v))).equals(witness)||!schema.read(one(mapper.retirementEvent(v))).equals(witness))reject(ErrorCode.CONTENT_MISMATCH);return d;
 }
 JsonNode approvalWitness(JsonNode receipt,String session,String context,String key,String time)throws IOException{RuntimeRetentionSchema.key(key);if(session==null||!session.matches("[!-~]{1,255}"))reject(ErrorCode.CONTENT_MISMATCH);var c=schema.validate("Context",schema.read(context));if(!TenantScope.requireCurrent().tenantId().equals(c.required("tenant_id").textValue()))reject(ErrorCode.CONTENT_MISMATCH);return schema.read(schema.canonical(Map.of("schema_version","1.0.0","receipt",receipt,"metadata_sha256",schema.hash(Map.of("session_id",session,"original_context",c,"key",key,"created_at",Instant.parse(time).toString())))));}
 JsonNode retirementWitness(JsonNode decision)throws IOException{return schema.read(schema.canonical(Map.of("schema_version","1.0.0","receipt",jsonSafeRetirement(decision),"decision_sha256",schema.hash(decision))));}
 JsonNode jsonSafeRetirement(JsonNode d)throws IOException{return schema.read(schema.canonical(Map.of("schema_version","1.0.0","decision_id",d.required("decision_id").textValue(),"policy_revision",d.required("policy_revision").textValue(),"operation_id",d.required("operation_id").textValue(),"effective_at",d.required("effective_at").textValue(),"request_body_sha256",d.required("original_request_sha256").textValue(),"revision","2","status","RETIREMENT_RECORDED")));}
 static Map<String,Object> parameters(String name,Object value){var result=new HashMap<String,Object>();result.put("userId",TenantScope.requireCurrent().subjectId());result.put(name,value);return result;}
 static Map<String,Object> values(RuntimeRetentionMapper.Row r){var v=new HashMap<String,Object>();v.put("userId",TenantScope.requireCurrent().subjectId());v.put("policyRevision",r.policyRevision());v.put("projectId",r.projectId());v.put("creator",r.creator());v.put("operationId",r.operationId());v.put("key",r.key());v.put("requestHash",r.requestHash());v.put("manifest",r.manifest());v.put("classification",r.classification());v.put("auditId",r.auditId());v.put("eventId",r.eventId());return v;}
 static PermissionProtocol.Scope scope(String tenant,String project){return new PermissionProtocol.Scope(tenant,project,project==null?"ENTERPRISE":"PROJECT",project==null?tenant:project);}
 static String nullable(JsonNode n){return n.isNull()?null:n.textValue();}
 static <T>T one(List<T> values){if(values.size()!=1)reject(ErrorCode.CONTENT_MISMATCH);return Objects.requireNonNull(values.get(0));}
 static void stage(String purpose){if(!Set.of("TASK_CREATION","PLAN_MAINTENANCE","RUN_CREATION").contains(purpose))reject(ErrorCode.ACCESS_DENIED);}
 static void reject(ErrorCode code){throw new TenantAccessException(code);}
}
